function isWeChatBrowser(){return/MicroMessenger/i.test(navigator.userAgent)}window.onload=function(){try{preloadAndSwapImage()}catch(e){console.error("Error in preloadAndSwapImage:",e)}document.getElementById("loadingScreen").style.display="none"},window.addEventListener("DOMContentLoaded",function(){if(isWeChatBrowser()){document.querySelectorAll(".wechat-video-wrapper").forEach((e,t)=>{const n=e.dataset.gif;e.innerHTML=`\n          <img src="${n}"\n               alt="Animated Services GIF ${t+1}"\n               class="wechat-services-gif"\n               style="width: 80%; height: auto; display: block; margin: 0 auto;" />\n        `})}}),document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("hamburger"),t=document.getElementById("menuOverlay");e.addEventListener("click",function(){this.classList.toggle("open"),t.classList.toggle("show")})}),document.addEventListener("DOMContentLoaded",function(){let e=document.querySelectorAll(".image-animate"),t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),t.unobserve(e.target))})},{threshold:.5});e.forEach(e=>{t.observe(e)})}),document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".image-transition"),t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting?e.target.classList.add("in-view"):e.target.classList.remove("in-view")})},{threshold:1});e.forEach(e=>t.observe(e))}),document.addEventListener("DOMContentLoaded",function(){let e=document.querySelectorAll(".text-animate, .gif-animate"),t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),t.unobserve(e.target))})},{threshold:.1});e.forEach(e=>{t.observe(e)})}),document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".image-container").forEach(e=>{e.addEventListener("click",function(){this.classList.contains("clicked")?this.classList.remove("clicked"):this.classList.add("clicked")})})}),document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".image-container").forEach(e=>{e.addEventListener("click",function(){this.classList.contains("clicked")?this.classList.remove("clicked"):this.classList.add("clicked")})})}),document.querySelectorAll(".tab").forEach(function(e){e.addEventListener("click",function(){document.querySelectorAll(".tab").forEach(function(e){e.classList.remove("active")}),this.classList.add("active")})}),document.fonts.ready.then(()=>{document.querySelectorAll(".card-body-intro").forEach(e=>{e.classList.remove("font-loading"),e.classList.add("font-loaded")})});